mapper.select:
SELECT child.region_code, child.region_name,
CASE WHEN parent.region_code = '36' THEN COALESCE( child_price.price_index, parent_price.price_index ) ELSE child_price.price_index END AS price_index,
CASE WHEN parent.region_code = '36' THEN COALESCE( child_price.change_rate, parent_price.change_rate ) ELSE child_price.change_rate END AS change_rate
FROM regions child
INNER JOIN regions parent ON parent.region_id = child.parent_region_id
LEFT JOIN jeonse_price_indices child_price ON child_price.region_id = child.region_id AND child_price.base_month = #{baseMonth}
LEFT JOIN jeonse_price_indices parent_price ON parent_price.region_id = parent.region_id AND parent_price.base_month = #{baseMonth}
WHERE child.region_level = 'SIGUNGU' AND parent.region_code = #{parentRegionCode}
ORDER BY child.region_code
